//! Pack-tag port vs the Python original: every case of `tests/data/tag_vectors.json` (generated by
//! `tests/tools/tag_vectors.py` from perseus/impl/fakecap.py) must evaluate identically.
use pc_shadow::tag::{self, Support, Tag};
use serde_json::{json, Value};

fn sup(v: &Value) -> Support {
    let a: Vec<i64> = v.as_array().unwrap().iter().map(|x| x.as_i64().unwrap()).collect();
    Support::new(a[0] as i32, a[1], a[2], a[3], a[4])
}
fn enc_s(s: &Support) -> Value {
    json!([s.kind, s.offset, s.stride, s.count, s.width])
}
fn tg(v: &Value) -> Tag {
    let a = v.as_array().unwrap();
    Tag {
        slots: a[0].as_i64().unwrap(),
        period: a[1].as_i64().unwrap(),
        support: sup(&a[2]),
        field: a[3].as_i64().unwrap() as i32,
        conj_of: a[4].as_u64(),
    }
}
fn enc_t(t: &Tag) -> Value {
    json!([t.slots, t.period, enc_s(&t.support), t.field, t.conj_of])
}
fn i(v: &Value) -> i64 {
    v.as_i64().unwrap()
}
fn f(v: &Value) -> f64 {
    v.as_f64().unwrap()
}

fn eval(name: &str, a: &[Value]) -> Value {
    match name {
        "support_ap" => enc_s(&Support::ap(i(&a[0]), i(&a[1]), i(&a[2]))),
        "support_block" => enc_s(&Support::block(i(&a[0]), i(&a[1]), i(&a[2]), i(&a[3]))),
        "union" => enc_s(&tag::union(sup(&a[0]), sup(&a[1]))),
        "intersect" => enc_s(&tag::intersect(sup(&a[0]), sup(&a[1]))),
        "f_add" => json!(tag::f_add(i(&a[0]) as i32, i(&a[1]) as i32)),
        "f_mult" => json!(tag::f_mult(i(&a[0]) as i32, i(&a[1]) as i32)),
        "lcm_capped" => json!(tag::lcm_capped(i(&a[0]), i(&a[1]), i(&a[2]))),
        "top" => enc_t(&tag::top(i(&a[0]))),
        "with_field" => enc_t(&tag::with_field(&tg(&a[0]), i(&a[1]) as i32)),
        "t_add" => enc_t(&tag::t_add(&tg(&a[0]), &tg(&a[1]))),
        "t_mult" => enc_t(&tag::t_mult(&tg(&a[0]), &tg(&a[1]))),
        "conj_pair" => enc_t(&tag::conj_pair(
            tg(&a[0]),
            a[1].as_u64().unwrap(),
            a[2].as_u64().unwrap(),
            &tg(&a[3]),
            &tg(&a[4]),
            a[5].as_bool().unwrap(),
        )),
        "from_signature" => enc_t(&tag::from_signature(i(&a[0]), i(&a[1]), i(&a[2]), i(&a[3]), i(&a[4]), i(&a[5]))),
        "min_routable_s" => json!(tg(&a[0]).min_routable_s()),
        "fold_collision_free_at" => json!(tg(&a[0]).fold_collision_free_at(i(&a[1]))),
        "periodic_at" => json!(tg(&a[0]).periodic_at(i(&a[1]))),
        "known" => json!(tg(&a[0]).known()),
        "t_mult_scalar" => enc_t(&tag::t_mult_scalar(&tg(&a[0]), f(&a[1]))),
        "t_add_scalar" => enc_t(&tag::t_add_scalar(&tg(&a[0]), f(&a[1]))),
        "t_rotate" => enc_t(&tag::t_rotate(&tg(&a[0]), i(&a[1]))),
        "t_bootstrap" => enc_t(&tag::t_bootstrap(&tg(&a[0]), i(&a[1]), i(&a[2]))),
        "t_square" => enc_t(&tag::t_square(&tg(&a[0]))),
        "t_mult_i" => enc_t(&tag::t_mult_i(&tg(&a[0]))),
        "t_conjugate" => enc_t(&tag::t_conjugate(&tg(&a[0]))),
        other => panic!("unknown case {other}"),
    }
}

#[test]
fn tag_vectors_match_python() {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/data/tag_vectors.json");
    let doc: Value = serde_json::from_slice(&std::fs::read(path).expect("tag vectors")).unwrap();
    let cases = doc["cases"].as_array().unwrap();
    let mut diffs = 0;
    let mut per: std::collections::BTreeMap<String, usize> = Default::default();
    for (k, c) in cases.iter().enumerate() {
        let name = c["f"].as_str().unwrap();
        *per.entry(name.to_string()).or_default() += 1;
        let got = eval(name, c["args"].as_array().unwrap());
        if got != c["out"] {
            diffs += 1;
            if diffs <= 10 {
                println!("case {k} {name} args {} : python {} rust {}", c["args"], c["out"], got);
            }
        }
    }
    println!("[tag] {} cases over {} functions, {diffs} differences", cases.len(), per.len());
    assert!(cases.len() >= 10_000);
    assert_eq!(diffs, 0);
}
